// 全身圖裡頭的位置：往右 10、以 (60,60) 為中心放大 1.06（頭大一點比較可愛），頭部配件也套同一個變換
const HEAD_T = 'translate(60 60) scale(1.06) translate(-50 -60)';

// 兩隻腳各畫一次的配件（x 位移 17）
const pair = s => s + `<g transform="translate(17 0)">${s}</g>`;
// 星形：n 角，外半徑 R、內半徑 r
const star = (cx, cy, R, r, n = 5) => 'M' + Array.from({ length: n * 2 }, (_, i) => { const a = -Math.PI / 2 + i * Math.PI / n, d = i % 2 ? r : R; return `${(cx + Math.cos(a) * d).toFixed(1)} ${(cy + Math.sin(a) * d).toFixed(1)}`; }).join(' L') + ' Z';

